-- HG shared platform migration (schema: lms)
-- Source: lms-hg/supabase/migrations/20260927160000_phase2_checkin_fixes.sql
-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- Phase 2 check-in fixes (forward-only):
--  * each learner's first QR scan records their own check-in time, even when a
--    manager recorded them manually beforehand (manual time kept separately);
--  * manual completion never overwrites a completion that won a race;
--  * session managers can list attendance candidates without legacy
--    teacher assignments.
BEGIN;

ALTER TABLE lms.session_attendances ADD COLUMN manual_recorded_at timestamptz;
ALTER TABLE lms.session_attendances ALTER COLUMN scanned_at DROP DEFAULT, ALTER COLUMN scanned_at DROP NOT NULL;
UPDATE lms.session_attendances SET manual_recorded_at = scanned_at, scanned_at = NULL
WHERE attendance_method = 'manual';
ALTER TABLE lms.session_attendances ADD CONSTRAINT session_attendances_times_check CHECK (
  (attendance_method = 'manual' AND scanned_at IS NULL AND manual_recorded_at IS NOT NULL)
  OR (attendance_method <> 'manual' AND scanned_at IS NOT NULL));
COMMENT ON COLUMN lms.session_attendances.scanned_at IS 'Learner''s first QR check-in time (server-side); never overwritten.';
COMMENT ON COLUMN lms.session_attendances.manual_recorded_at IS 'When a manager recorded the attendance manually, if they did.';

CREATE OR REPLACE FUNCTION lms.scan_session_qr(qr_token text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  learner uuid := auth.uid();
  scanned timestamptz := now();
  grace interval := lms_private.session_checkin_grace();
  account record;
  qr record;
  target record;
  target_module record;
  attendance_id uuid;
  attendance_scanned_at timestamptz;
  attendance_manual_at timestamptz;
  attendance_method text;
  newly_completed_at timestamptz;
  already_attended boolean := false;
  progress record;
BEGIN
  IF learner IS NULL THEN
    RETURN jsonb_build_object('result', 'unauthenticated');
  END IF;
  -- Shares the row lock with deactivation/demotion, which must wait for us.
  SELECT role, is_active, deleted_at INTO account FROM lms.users WHERE id = learner FOR SHARE;
  IF NOT FOUND OR NOT account.is_active OR account.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('result', 'inactive_account');
  END IF;
  IF account.role NOT IN ('user', 'admin') THEN
    RETURN jsonb_build_object('result', 'role_not_allowed');
  END IF;
  IF qr_token IS NULL OR qr_token !~ '^[A-Za-z0-9_-]{43}$' THEN
    RETURN jsonb_build_object('result', 'invalid_token');
  END IF;

  SELECT session_id INTO qr FROM lms.session_qr_tokens
  WHERE token_hash = sha256(convert_to(qr_token, 'UTF8'));
  IF NOT FOUND THEN
    RETURN jsonb_build_object('result', 'invalid_token');
  END IF;
  -- Lock order session -> token matches the management RPCs (no deadlock).
  -- FOR SHARE makes an in-flight cancel/revoke finish first; it is then observed.
  SELECT id, module_id, title, starts_at, ends_at, status, deleted_at INTO target
  FROM lms.curriculum_sessions WHERE id = qr.session_id FOR SHARE;
  SELECT id, session_id, valid_from, expires_at, revoked_at INTO qr
  FROM lms.session_qr_tokens WHERE token_hash = sha256(convert_to(qr_token, 'UTF8')) FOR SHARE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('result', 'invalid_token');
  END IF;
  IF qr.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('result', 'revoked_token');
  END IF;
  IF scanned > qr.expires_at THEN
    RETURN jsonb_build_object('result', 'expired_token');
  END IF;
  IF scanned < qr.valid_from THEN
    RETURN jsonb_build_object('result', 'session_not_open');
  END IF;
  IF target.id IS NULL OR target.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('result', 'session_unavailable');
  END IF;
  IF target.status = 'cancelled' THEN
    RETURN jsonb_build_object('result', 'session_cancelled');
  END IF;
  IF target.status = 'completed' OR scanned > target.ends_at + grace THEN
    RETURN jsonb_build_object('result', 'session_closed');
  END IF;
  IF scanned < target.starts_at - grace THEN
    RETURN jsonb_build_object('result', 'session_not_open');
  END IF;

  SELECT id, title, module_code, is_published, deleted_at INTO target_module
  FROM lms.modules WHERE id = target.module_id;
  IF NOT FOUND OR target_module.deleted_at IS NOT NULL OR NOT target_module.is_published THEN
    RETURN jsonb_build_object('result', 'module_unavailable');
  END IF;
  IF EXISTS (SELECT 1 FROM lms.session_teachers WHERE session_id = target.id AND admin_id = learner) THEN
    RETURN jsonb_build_object('result', 'teacher_cannot_attend');
  END IF;

  -- The QR stays valid for everyone; each learner's FIRST scan records their
  -- own check-in time. A manually recorded row (scanned_at IS NULL) is
  -- upgraded by that first scan; its manual_recorded_at is kept.
  INSERT INTO lms.session_attendances AS a (session_id, learner_id, scanned_at, attendance_method, created_at)
  VALUES (target.id, learner, scanned, 'qr', scanned)
  ON CONFLICT (session_id, learner_id) DO UPDATE SET scanned_at = EXCLUDED.scanned_at, attendance_method = 'qr'
  WHERE a.scanned_at IS NULL
  RETURNING a.id, a.scanned_at, a.attendance_method, a.manual_recorded_at
  INTO attendance_id, attendance_scanned_at, attendance_method, attendance_manual_at;

  IF attendance_id IS NULL THEN
    -- Repeat scan: strictly idempotent, the original check-in time is kept.
    already_attended := true;
    SELECT a.id, a.scanned_at, a.attendance_method, a.manual_recorded_at
    INTO attendance_id, attendance_scanned_at, attendance_method, attendance_manual_at
    FROM lms.session_attendances a WHERE a.session_id = target.id AND a.learner_id = learner;
  ELSE
    -- Only a first completion sets provenance; an existing completion keeps it.
    INSERT INTO lms.learner_progress AS lp (learner_id, module_id, status, started_at, completed_at,
      source_session_id, completion_method)
    VALUES (learner, target.module_id, 'completed', scanned, scanned, target.id, 'qr_attendance')
    ON CONFLICT (learner_id, module_id) DO UPDATE SET status = 'completed',
      started_at = coalesce(lp.started_at, EXCLUDED.started_at),
      completed_at = EXCLUDED.completed_at, source_session_id = EXCLUDED.source_session_id,
      completion_method = EXCLUDED.completion_method, marked_by = NULL
    WHERE lp.status <> 'completed'
    RETURNING lp.completed_at INTO newly_completed_at;

    IF newly_completed_at IS NOT NULL THEN
      UPDATE lms.session_attendances SET completion_granted_at = newly_completed_at
      WHERE id = attendance_id;
    END IF;

    INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
    VALUES (learner, 'session_attendance_recorded', 'session_attendances', attendance_id, jsonb_build_object(
      'session_id', target.id, 'module_id', target.module_id, 'attendance_method', 'qr',
      'qr_token_id', qr.id, 'completion_granted', newly_completed_at IS NOT NULL,
      'manual_recorded_at', attendance_manual_at));
    IF newly_completed_at IS NOT NULL THEN
      INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
      VALUES (learner, 'module_completed', 'modules', target.module_id, jsonb_build_object(
        'module_id', target.module_id, 'session_id', target.id, 'attendance_id', attendance_id,
        'completion_method', 'qr_attendance', 'learner_initiated', true));
    END IF;
  END IF;

  SELECT status, completed_at, completion_method, source_session_id INTO progress
  FROM lms.learner_progress WHERE learner_id = learner AND module_id = target.module_id;

  RETURN jsonb_build_object(
    'result', CASE WHEN already_attended THEN 'already_attended'
      WHEN newly_completed_at IS NOT NULL THEN 'completed' ELSE 'attended_previously_completed' END,
    'session', jsonb_build_object('id', target.id, 'title', target.title,
      'starts_at', target.starts_at, 'ends_at', target.ends_at),
    'module', jsonb_build_object('id', target_module.id, 'title', target_module.title,
      'module_code', target_module.module_code),
    'teachers', (SELECT coalesce(jsonb_agg(coalesce(u.full_name, 'Admin') ORDER BY u.full_name), '[]'::jsonb)
      FROM lms.session_teachers st JOIN lms.users u ON u.id = st.admin_id WHERE st.session_id = target.id),
    'attendance', jsonb_build_object('id', attendance_id, 'scanned_at', attendance_scanned_at,
      'method', attendance_method, 'manual_recorded_at', attendance_manual_at),
    'progress', jsonb_build_object('status', progress.status, 'completed_at', progress.completed_at,
      'completion_method', progress.completion_method,
      'source_session_id', progress.source_session_id),
    'notes_unlocked', progress.status = 'completed');
END;
$$;

CREATE OR REPLACE FUNCTION lms.add_session_attendees(target_session_id uuid, learner_ids uuid[]) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  target lms.curriculum_sessions;
  requested integer := coalesce(cardinality(learner_ids), 0);
  added integer;
BEGIN
  target := lms_private.lock_managed_session(target_session_id);
  IF target.status = 'cancelled' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Cannot add attendees to a cancelled session';
  END IF;
  IF requested = 0 OR requested > 500 OR array_position(learner_ids, NULL) IS NOT NULL
     OR (SELECT count(DISTINCT l) FROM unnest(learner_ids) l) <> requested THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Invalid learner selection';
  END IF;
  IF (SELECT count(*) FROM lms.users WHERE id = ANY (learner_ids)
      AND role = 'user' AND is_active AND deleted_at IS NULL) <> requested THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'One or more learners are not eligible';
  END IF;

  WITH inserted AS (
    -- Manual rows carry no QR check-in time; a later first scan sets it.
    INSERT INTO lms.session_attendances (session_id, learner_id, scanned_at, manual_recorded_at,
      attendance_method, recorded_by)
    SELECT target.id, l, NULL, now(), 'manual', auth.uid() FROM unnest(learner_ids) l
    ON CONFLICT (session_id, learner_id) DO NOTHING
    RETURNING id, learner_id
  ), progress AS (
    INSERT INTO lms.learner_progress (learner_id, module_id, status, started_at)
    SELECT learner_id, target.module_id, 'in_progress', now() FROM inserted
    ON CONFLICT (learner_id, module_id) DO NOTHING
  ), logged AS (
    INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
    SELECT learner_id, 'session_attendance_recorded', 'session_attendances', id, jsonb_build_object(
      'session_id', target.id, 'module_id', target.module_id, 'attendance_method', 'manual',
      'recorded_by', auth.uid(), 'completion_granted', false)
    FROM inserted
  )
  SELECT count(*) INTO added FROM inserted;
  RETURN added;
END;
$$;

CREATE OR REPLACE FUNCTION lms.set_module_completion(target_learner_id uuid, target_module_id uuid, completed boolean)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  actor uuid := auth.uid();
  existing lms.learner_progress;
  won uuid;
  stamp timestamptz := now();
BEGIN
  PERFORM 1 FROM lms.users WHERE id = actor FOR SHARE;
  PERFORM 1 FROM lms.module_teaching_permissions
  WHERE user_id = actor AND module_id = target_module_id FOR SHARE;
  IF NOT lms.is_active_app_user(actor) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Account is inactive';
  END IF;
  IF NOT (lms.is_super_admin() OR (lms.can_teach_module(target_module_id) AND (
      lms.is_assigned_teacher(target_learner_id)
      OR EXISTS (SELECT 1 FROM lms.learner_progress WHERE learner_id = target_learner_id
        AND module_id = target_module_id AND teacher_id = actor)
      OR lms.is_session_teacher_for_learner(target_learner_id, target_module_id)))) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Learner access denied';
  END IF;
  PERFORM 1 FROM lms.modules WHERE id = target_module_id AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Module not found';
  END IF;

  SELECT * INTO existing FROM lms.learner_progress
  WHERE learner_id = target_learner_id AND module_id = target_module_id FOR UPDATE;

  IF completed THEN
    IF existing.status = 'completed' THEN
      RETURN jsonb_build_object('changed', false, 'status', 'completed');
    END IF;
    INSERT INTO lms.learner_progress AS lp (learner_id, module_id, status, started_at, completed_at,
      marked_by, completion_method)
    VALUES (target_learner_id, target_module_id, 'completed', stamp, stamp, actor, 'manual_admin')
    ON CONFLICT (learner_id, module_id) DO UPDATE SET status = 'completed',
      started_at = coalesce(lp.started_at, EXCLUDED.started_at),
      completed_at = EXCLUDED.completed_at, marked_by = EXCLUDED.marked_by,
      completion_method = 'manual_admin', source_session_id = NULL
    -- A concurrent QR (or other) completion that committed first keeps its
    -- timestamp and provenance; this call then changes nothing.
    WHERE lp.status <> 'completed'
    RETURNING lp.id INTO won;
    IF won IS NULL THEN
      RETURN jsonb_build_object('changed', false, 'status', 'completed');
    END IF;
    INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
    VALUES (target_learner_id, 'module_completed', 'modules', target_module_id, jsonb_build_object(
      'module_id', target_module_id, 'marked_by', actor, 'learner_initiated', false,
      'completion_method', 'manual_admin'));
    RETURN jsonb_build_object('changed', true, 'status', 'completed');
  END IF;

  IF existing.id IS NULL OR existing.status <> 'completed' THEN
    RETURN jsonb_build_object('changed', false, 'status', coalesce(existing.status, 'not_started'));
  END IF;
  UPDATE lms.learner_progress
  SET status = CASE WHEN started_at IS NOT NULL THEN 'in_progress' ELSE 'not_started' END,
    completed_at = NULL, marked_by = NULL, completion_method = NULL, source_session_id = NULL
  WHERE id = existing.id;
  INSERT INTO lms.activity_logs (user_id, event, entity_type, entity_id, metadata)
  VALUES (target_learner_id, 'module_updated', 'modules', target_module_id, jsonb_build_object(
    'module_id', target_module_id, 'action', 'unmarked_complete', 'unmarked_by', actor,
    'previous_completion_method', existing.completion_method,
    'previous_source_session_id', existing.source_session_id,
    'previous_completed_at', existing.completed_at));
  RETURN jsonb_build_object('changed', true, 'status',
    CASE WHEN existing.started_at IS NOT NULL THEN 'in_progress' ELSE 'not_started' END);
END;
$$;

-- Manual attendee picker: session managers (Phase 1 permissions + session
-- authority) see active learners not yet attending, without needing legacy
-- teacher assignments or manage_users. Only name/email needed to pick.
CREATE FUNCTION lms.list_session_attendance_candidates(target_session_id uuid)
RETURNS TABLE (candidate_id uuid, candidate_name text, candidate_email text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NOT lms.is_session_manager(target_session_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Session access denied';
  END IF;
  RETURN QUERY
  SELECT u.id, u.full_name, u.email FROM lms.users u
  WHERE u.role = 'user' AND u.is_active AND u.deleted_at IS NULL
    AND NOT EXISTS (SELECT 1 FROM lms.session_attendances sa
      WHERE sa.session_id = target_session_id AND sa.learner_id = u.id)
  ORDER BY u.full_name NULLS LAST, u.email;
END;
$$;
REVOKE ALL ON FUNCTION lms.list_session_attendance_candidates(uuid) FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION lms.list_session_attendance_candidates(uuid) TO authenticated;

COMMIT;
